async function connect(){
  if(S.simulation||S.connecting&&S.connectingGeneration===S.generation)return;
  const generation=S.generation,mode=S.mode,revision=S.instrumentRevision,category=S.category;
  S.connecting=true;S.connectingGeneration=generation;S.connectError=null;renderHeader();notice(`Ansluter IG ${mode.toUpperCase()} · verifierar konto och priser…`);
  try{
    const result=await api('/api/ig/connect',{method:'POST',body:{environment:mode}});
    if(generation!==S.generation)return;
    environmentStates=result.environments??environmentStates;const status=result.environments?.[mode];if(status?.status!=='connected')throw Error(status?.error??'IG-anslutningen saknar verifierat konto');
    await refresh();if(generation!==S.generation)return;
    await loadCatalog(category);if(generation!==S.generation)return;
    // Anslutningen får inte ersätta ett instrument som användaren väljer under väntan.
    if(!S.current&&revision===S.instrumentRevision&&category===S.category){
      await restoreChart();
    }
    if(generation!==S.generation)return;
    if(S.connection?.status!=='connected')throw Error(S.connection?.error??'Kontodata kunde inte verifieras efter anslutning');
    notice(`IG ${mode.toUpperCase()} ansluten. ${S.market?'Diagrammet visar valt instrument.':'Inget tillgängligt instrument hittades; sök i vänsterpanelen.'} Priser läses via REST; orderstatus visas separat.`);
  }catch(e){if(generation===S.generation){S.connectError=`IG ${mode.toUpperCase()} kunde inte anslutas: ${e.message}`;notice(S.connectError);throw e;}}
  finally{if(S.connectingGeneration===generation){S.connecting=false;renderHeader();}}
}
async function analyze(){if(!S.selected.size)throw Error('Välj minst ett instrument');if(S.simulation){simulateAnalysis();return;}await syncSelection();const generation=S.generation;S.analysis={status:'running',steps:[{status:'Arbetar'}]};renderSignals();renderSession();renderSelection();try{const a=await api('/api/ig/analysis',{method:'POST',body:selection()});if(generation!==S.generation)return;S.analysis=a;await refresh();toast('Analysen är klar. Läs agentsignalerna bredvid diagrammet.');}catch(e){if(generation===S.generation){S.analysis={status:'failed',error:e.message};renderSignals();throw e;}}finally{renderSelection();}}
function openReview(title,html,callback,enabled=true){S.review=callback;$('review-title').textContent=title;$('review-content').innerHTML=html;$('confirm-order').disabled=!enabled;$('confirm-order').textContent=S.simulation?'Bekräfta simulering':'Bekräfta';$('review-dialog').showModal();}
async function reviewOrder(){if(S.session?.status==='running'&&S.session.marginPercent!==undefined){$('holding').value=S.session.horizonMinutes;$('auto-close').checked=true;}const t=ticket(),calc=scenario(t);if(!calc.valid||!quoteIsFresh(S.market))throw Error('Orderunderlag eller färsk kvot saknas');const order={epic:S.current,direction:S.direction,size:t.size,entry:t.entry,stopLevel:t.stop,targetLevel:t.target,orderType:S.orderType,holdingMinutes:Number($('holding').value),autoClose:$('auto-close').checked};
  let serverDraft=null;
  if(!S.simulation){serverDraft=await api('/api/ig/order-preview',{method:'POST',body:{environment:S.mode,...order}});t.entry=serverDraft.entry;order.entry=serverDraft.entry;calc.risk=serverDraft.risk;calc.exposure=serverDraft.exposure;calc.margin=serverDraft.margin;calc.reward=serverDraft.reward??Math.abs(t.target-t.entry)*calc.risk/Math.abs(t.entry-t.stop);}
  const generation=S.generation;
  openReview('Granska order',`<div class="selected-summary">${S.simulation?'DEMODATA · lokal simulering':`IG ${S.mode.toUpperCase()}`} · ${esc(nameOf(order.epic))}</div><div class="review-lines"><div class="row"><span>Riktning / storlek</span><b>${order.direction==='BUY'?'Köp':'Sälj'} · ${number(order.size)} kontrakt</b></div><div class="row"><span>Ingång / SL / TP</span><b>${price(t.entry)} / ${price(t.stop)} / ${price(t.target)}</b></div><div class="row"><span>Risk / potentiell vinst</span><b>${money(calc.risk)} / ${money(calc.reward)}</b></div><div class="row"><span>Innehavstid</span><b>${order.holdingMinutes} minuter</b></div></div><p class="field-note">${S.simulation?'Ingen verklig order. Limitordrar väntar på simulerad fyllnad.':esc(S.execution.reason)}</p>`,async()=>{
    if(generation!==S.generation)throw Error('Kontot ändrades; granska ett nytt orderunderlag');
    if(!S.simulation){const result=await api('/api/ig/order-confirm',{method:'POST',body:{environment:S.mode,draftId:serverDraft.id}});await refresh();toast(result.status==='accepted'?'IG accepterade ordern · inväntar positionssynk':result.error??'IG inväntar orderbekräftelse');return;}
    if(S.quoteState==='order-error'){toast('Orderfel: simulerad mäklaravvisning. Ingen position öppnad.');S.pending.push({...order,id:crypto.randomUUID(),status:'failed',blocker:'Simulerad orderavvisning'});renderTrades();return;}
    if(S.positions.length>=S.maxPositions)throw Error('Gränsen för samtidiga positioner är nådd');
    if(order.orderType==='LIMIT'){S.pending.push({...order,id:crypto.randomUUID(),status:'pending'});S.tradeTab='pending';}else addSimulationPosition(order);renderTrades();renderChart();toast('Simulerad order accepterad.');
  },S.simulation||S.execution.enabled);
}
function addSimulationPosition(order){S.positions.push({dealId:crypto.randomUUID(),epic:order.epic,instrumentName:nameOf(order.epic),direction:order.direction,size:order.size,level:order.entry,stopLevel:order.stopLevel,limitLevel:order.targetLevel,currency:S.account.currency,openedAt:Date.now(),closeAt:order.autoClose?Date.now()+order.holdingMinutes*60000:null});S.tradeTab='open';}
async function doubleUp(id){const p=S.positions.find(p=>p.dealId===id),draft=increaseDraft(p);await chooseInstrument(draft.epic);S.direction=draft.direction;$('size').value=draft.size;$('stop').value=draft.stop??'';$('target').value=draft.target??'';S.orderType='MARKET';recalculate();toast(`Double up: ny order för ${number(draft.size)} kontrakt. Total storlek blir ${number(draft.size*2)}; risk och marginal ökar. Granska ordern.`);}
function rollOver(id){const generation=S.generation,binding=S.connection?.connectionGeneration;const p=S.positions.find(p=>p.dealId===id);if(!p)throw Error('Positionen saknas');const minutes=Number($('holding').value),next=extendDeadline(p,minutes);openReview('Roll over · förläng innehavstid',`<div class="selected-summary">${esc(nameOf(p.epic))} · ${S.simulation?'DEMODATA':`IG ${S.mode.toUpperCase()}`}</div><div class="review-lines"><div class="row"><span>Ny planerad tid</span><b>${time(next)} (+${minutes} min)</b></div></div><p class="field-note">Detta ändrar en planerad stängningsbegäran. CFD-kontraktet har ingen fast utgångstid. Storlek, stop-loss och målpris ändras inte. ${S.simulation?'':'Servern måste ha en verifierad tidsstängning för positionen.'}</p>`,async()=>{if(generation!==S.generation)throw Error('Kontot ändrades; granska igen');if(!S.simulation){await api('/api/ig/rollover',{method:'POST',body:{environment:S.mode,dealId:p.dealId,minutes,connectionGeneration:binding}});await refresh();toast('IG-positionens planerade tidsstängning förlängd');return;}p.closeAt=next;renderTrades();toast('Simulerad innehavstid förlängd.');},S.simulation||S.execution.enabled);}
function closePosition(id){const generation=S.generation,binding=S.connection?.connectionGeneration;const p=S.positions.find(p=>p.dealId===id);if(!p)throw Error('Positionen saknas');openReview('Stäng position',`<div class="selected-summary">${esc(nameOf(p.epic))} · ${number(p.size)} kontrakt</div><p class="field-note">${S.simulation?'DEMODATA: simulerat avslut till aktuell kvot.':'Stängning kräver serverns verifierade IG-orderfunktion. En begäran är inte ett bekräftat avslut.'}</p>`,async()=>{
  if(generation!==S.generation)throw Error('Kontot ändrades; granska igen');if(!S.simulation){const result=await api('/api/ig/close',{method:'POST',body:{environment:S.mode,dealId:p.dealId,connectionGeneration:binding}});await refresh();toast(result.status==='confirmed'?'IG bekräftade stängningen':result.error??'Stängning begärd · inväntar IG-bekräftelse');return;}p.closing=true;renderTrades();await new Promise(r=>setTimeout(r,450));p.closing=false;
  if(S.quoteState==='order-error'||S.quoteState==='disconnected'||S.quoteState==='stale'){p.closeError='Simulerad avvisning eller prisfel';renderTrades();return;}
  const calc=positionPnl(p);S.closed.unshift({...p,entry:p.level,exit:calc.current,pnl:calc.pnl,costs:null,closedAt:Date.now(),reason:'Manuell stängning'});S.positions=S.positions.filter(x=>x.dealId!==id);renderTrades();renderChart();toast('Stängning bekräftad · simulering');
},S.simulation||S.execution.enabled);}
