document.addEventListener('click',safe(async e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const id=b.dataset.importCopy??b.dataset.importDelete;if(!id)return;const row=importedSignals.find(x=>x.id===id);if(!row)return;if(b.dataset.importDelete){await api('/api/ig/imported-signals',{method:'DELETE',body:{environment:S.mode,id}});await loadImportedSignals();return;}if(!importedMatchesAccount(row))throw Error('Signalutkastet tillhör en tidigare eller annan kontoanslutning.');if(Date.now()>=row.validUntil)throw Error('Signalutkastet har gått ut.');const generation=S.generation,limit=$('import-copy-limit').checked;await chooseInstrument(row.epic);if(generation!==S.generation||S.current!==row.epic)return;if(!S.market||!quoteIsFresh(S.market))throw Error('Kopiering blockerad: färsk verifierad IG-kvot saknas.');if(!importedMatchesAccount(row))throw Error('Signalutkastet tillhör en tidigare eller annan kontoanslutning.');if(Date.now()>=row.validUntil)throw Error('Signalutkastet har gått ut.');S.direction=row.direction;S.orderType=limit?'LIMIT':'MARKET';$('limit').value=row.entryLevel;$('stop').value=row.stopLevel;$('target').value=row.targetLevel;recalculate();$('import-signal-dialog').close();showTradingView();toast('Ej verifierad signal kopierad till orderutkast. Granska separat; ingen order skickad.');}));
