document.addEventListener('click',safe(async e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const d=b.dataset;
  if(d.workspaceView){showWorkspaceView(d.workspaceView);return;}if(d.reloadMarkets){const generation=S.generation;await loadCatalog('forex',{force:true});if(generation!==S.generation)return;await loadCatalog('crypto',{force:true});if(generation!==S.generation)return;if(!visibleMarkets().length){const first=S.catalog.find(m=>['forex','crypto'].includes(kind(m)));if(first)await changeCategory(kind(first));}return;}if(d.tool){$('tools-dialog').close();if(d.tool==='markets')$('markets-open').click();else if(d.tool==='session')$('session-open').click();else if(d.tool==='settings')$('settings-open').click();else{showTradingView();document.querySelector('.workspace').dataset.panel='activity';if(['open','closed'].includes(d.tool))S.tradeTab=d.tool;renderTrades();$('signals').scrollIntoView({block:'nearest'});}return;}if(d.close){$(d.close).close();return;}if(d.mode||d.accountMode){if($('settings-dialog').open){clearCredentialFields();$('settings-dialog').close();}await switchMode(d.mode??d.accountMode);return;}if(d.category){await changeCategory(d.category);return;}if(d.catalogCategory){if(['all','favorites'].includes(d.catalogCategory)){S.catalogView=d.catalogCategory;$('catalog-search').value='';renderCatalog();await loadCatalogView();}else await changeCategory(d.catalogCategory);return;}
  if(d.panel){document.querySelector('.workspace').dataset.panel=d.panel;document.querySelectorAll('[data-panel]').forEach(x=>{if(x.tagName==='BUTTON')x.classList.toggle('active',x.dataset.panel===d.panel);});return;}
  if(d.marketMore&&['forex','crypto'].includes(d.marketMore)){marketVisible[d.marketMore]+=12;renderMarketsPage();return;}
  if(d.marketAnalyze){const generation=S.generation;S.selected=new Set([d.marketAnalyze]);await syncSelection();if(generation!==S.generation)return;await analyze();renderMarketsPage();return;}
  if(d.marketOrder){const generation=S.generation;showTradingView();await chooseInstrument(d.marketSymbol);if(generation!==S.generation||S.current!==d.marketSymbol)return;S.direction=d.marketOrder;recalculate();toast('Orderutkast öppnat. Granska storlek, stop-loss och mål före bekräftelse.');return;}
  if(d.chart){showTradingView();await chooseInstrument(d.chart);if($('catalog-dialog').open)$('catalog-dialog').close();return;}if(d.star){S.favorites.has(d.star)?S.favorites.delete(d.star):S.favorites.add(d.star);if(S.simulation)localStorage.setItem('trading-workspace-favorites',JSON.stringify([...S.favorites]));else{try{const result=await api('/api/ig/preferences',{method:'POST',body:{environment:S.mode,favorites:[...S.favorites],revision:S.preferencesRevision}});const prefs=result.preferences??result;S.favorites=new Set(prefs.favorites??[]);S.preferencesRevision=prefs.revision??S.preferencesRevision;}catch(e){await refresh();throw e;}}renderInstruments();renderCatalog();subscribeRealtime();return;}
  if(d.frame){S.chartFrame=d.frame;document.querySelectorAll('[data-frame]').forEach(x=>x.classList.toggle('active',x.dataset.frame===d.frame));if(S.current)await chooseInstrument(S.current,{reset:false});return;}
  if(d.direction){S.direction=d.direction;recalculate();return;}if(d.orderType){S.orderType=d.orderType;recalculate();return;}if(d.percent){const t=ticket(),size=sizeForCapitalRisk({...t,percent:Number(d.percent)});if(size==null)throw Error('Riskandel kräver verifierat punktvärde, konto och stop-loss.');$('size').value=size;recalculate();return;}
  if(d.trades){S.tradeTab=d.trades;renderTrades();return;}if(d.copy){showTradingView();await copySignal(d.copy);return;}if(d.double){await doubleUp(d.double);return;}if(d.roll){rollOver(d.roll);return;}if(d.closePosition){closePosition(d.closePosition);return;}
  if(d.selectCategory){const markets=S.catalog.filter(m=>kind(m)===d.selectCategory);if(new Set([...S.selected,...markets.map(m=>m.epic)]).size>10)throw Error('Befintlig IG-analysgräns är 10 instrument');markets.forEach(m=>S.selected.add(m.epic));renderCatalog();renderInstruments();await syncSelection();return;}
  if(d.fill){const p=S.pending.find(p=>p.id===d.fill);if(!S.simulation||!p)return;if(S.quoteState!=='ready')throw Error('Simulerad fyllnad stoppad av datastatus');if(S.positions.length>=S.maxPositions)throw Error('Max samtidiga positioner nådd');const generation=S.generation;p.status='accepted';renderTrades();setTimeout(()=>{if(!S.simulation||generation!==S.generation)return;S.pending=S.pending.filter(x=>x.id!==p.id);addSimulationPosition(p);renderTrades();renderChart();toast('Simulerad order fylld · position öppen');},300);return;}
  if(d.cancel){S.pending=S.pending.filter(p=>p.id!==d.cancel);renderTrades();}
}));
document.addEventListener('change',safe(async e=>{const epic=e.target.dataset.select;if(!epic)return;if(e.target.checked&&!S.selected.has(epic)&&S.selected.size>=10){e.target.checked=false;throw Error('Max 10 instrument per analys. Avmarkera ett instrument först.');}e.target.checked?S.selected.add(epic):S.selected.delete(epic);renderInstruments();renderCatalog();await syncSelection();}));
setInterval(safe(async()=>{
  if(!S.simulation){if(document.hidden)return;renderChart();if(!realtimeHealthy())await refresh();else{renderHeader();recalculate();renderSignals();renderSession();}if(Date.now()-catalogResumeAt>=60000){const categories=$('catalog-dialog').open&&!['favorites','all'].includes(S.catalogView)?[S.catalogView]:[S.category,S.category==='crypto'?'forex':'crypto'];const next=nextCatalogCategory(S.catalogState,categories);if(next)await loadCatalog(next);}return;}
  if(S.market&&S.quoteState!=='stale'&&S.quoteState!=='disconnected')S.market.quote.receivedAt=Date.now();
  if(S.session?.status==='running'){if(Date.now()>=S.session.endsAt){S.session.status='completed';}else if(Date.now()>=S.session.nextRunAt&&S.quoteState==='ready'){S.session.nextRunAt=Date.now()+S.session.intervalMinutes*60000;simulateAnalysis();}}
  // Avslut simuleras först efter kvotkontroll; ett fel lämnar positionen öppen.
  for(const p of [...S.positions])if(p.closeAt&&Date.now()>=p.closeAt&&!p.closeError){if(S.quoteState==='stale'||S.quoteState==='disconnected'||S.quoteState==='order-error'){p.closeError='Tidsstängning misslyckades · demodata';continue;}const calc=positionPnl(p);S.closed.unshift({...p,entry:p.level,exit:calc.current,pnl:calc.pnl,costs:null,closedAt:Date.now(),reason:'Planerad tidsstängning · simulerad'});S.positions=S.positions.filter(x=>x.dealId!==p.dealId);}
  renderTrades();renderSignals();renderSession();recalculate();
}),5000);
